import{_ as s,c as n,o as l,ae as a,j as e,a as o}from"./chunks/framework.CMFi8ROq.js";const u=JSON.parse('{"title":"token","description":"","frontmatter":{},"headers":[],"relativePath":"ai-guide/token.md","filePath":"ai-guide/token.md","lastUpdated":1777978720000}'),r={name:"ai-guide/token.md"},d={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},T={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.439ex"},xmlns:"http://www.w3.org/2000/svg",width:"9.581ex",height:"2.394ex",role:"img",focusable:"false",viewBox:"0 -864 4234.8 1058","aria-hidden":"true"};function i(Q,t,p,m,c,h){return l(),n("div",null,[t[7]||(t[7]=a('<h1 id="token" tabindex="-1">token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;token&quot;">​</a></h1><p><code>token</code> 是大模型读写文本时的最小计算单位。大模型是无法直接理解“苹果”或者“apple”这种抽象概念的，模型的本质是数学函数，它处理文本的过程大概如下：它先把文本拆成一小块一小块的单位（<code>token</code>），并将其映射为数字（<code>ID</code>），然后将这些数字转换为向量（<code>vector</code>），最后输入到神经网络中进行计算。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>文本 → Token → 数字（ID）→ 向量 → 神经网络 -&gt; Token -&gt; 文本</span></span></code></pre></div><p><code>token</code> 的切分规则（Tokenization）并不是固定的，它取决于模型使用的分词器（Tokenizer）。</p><ul><li>英文规则：通常是一个单词，或者长单词的一部分。例如 Learning 可能是 1 个 <code>token</code>，而 Transformer 可能被拆分为 Trans 和 former。</li><li>中文规则：由于中文没有空格，分词更复杂。通常一个汉字对应 1-2 个 <code>token</code>，词组（如“人工智能”）有时会被视为整体。</li><li>符号与空格：标点符号和代码中的缩进（Tab/Space）也都是独立的 Token。</li></ul><p>模型的计算复杂度，跟 <code>token</code> 数量有关, token 越多，计算量是平方级增长。Transformer 的注意力机制，本质上是在 <code>token</code> 之间两两建立关系，所以模型限制的是 <code>token</code> 的数量（而非大小，例如多少KB），并且按 <code>token</code> 数量计费。</p><p><strong>还有一个问题：为什么大模型无法直接理解一整句话，把整句话都映射为数字不可以吗？</strong></p><p>这个问题直戳大模型（LLM）底层设计的核心。作为一个 AI 专家，我可以用一个形象的比喻和三个硬核的技术理由来帮你拆解：<strong>为什么 AI 不能把“整句话”当成一个数字。</strong></p><h5 id="_1-组合爆炸问题-数学上的不可能" tabindex="-1">1. 组合爆炸问题（数学上的不可能） <a class="header-anchor" href="#_1-组合爆炸问题-数学上的不可能" aria-label="Permalink to &quot;1. 组合爆炸问题（数学上的不可能）&quot;">​</a></h5><p>如果把“一整句话”映射为一个数字（Token），那么 AI 的“字典”会瞬间爆炸。</p>',10)),e("ul",null,[t[5]||(t[5]=e("li",null,[e("strong",null,"单词量"),o("：英语常用单词约 10 万个。")],-1)),e("li",null,[t[2]||(t[2]=e("strong",null,"句子量",-1)),t[3]||(t[3]=o("：一句话如果只有 10 个词，可能的排列组合就是 ")),e("mjx-container",d,[(l(),n("svg",T,t[0]||(t[0]=[a('<g stroke="currentColor" fill="currentColor" stroke-width="0" transform="scale(1,-1)"><g data-mml-node="math"><g data-mml-node="mn"><path data-c="31" d="M213 578L200 573Q186 568 160 563T102 556H83V602H102Q149 604 189 617T245 641T273 663Q275 666 285 666Q294 666 302 660V361L303 61Q310 54 315 52T339 48T401 46H427V0H416Q395 3 257 3Q121 3 100 0H88V46H114Q136 46 152 46T177 47T193 50T201 52T207 57T213 61V578Z" style="stroke-width:3;"></path><path data-c="30" d="M96 585Q152 666 249 666Q297 666 345 640T423 548Q460 465 460 320Q460 165 417 83Q397 41 362 16T301 -15T250 -22Q224 -22 198 -16T137 16T82 83Q39 165 39 320Q39 494 96 585ZM321 597Q291 629 250 629Q208 629 178 597Q153 571 145 525T137 333Q137 175 145 125T181 46Q209 16 250 16Q290 16 318 46Q347 76 354 130T362 333Q362 478 354 524T321 597Z" transform="translate(500,0)" style="stroke-width:3;"></path><path data-c="30" d="M96 585Q152 666 249 666Q297 666 345 640T423 548Q460 465 460 320Q460 165 417 83Q397 41 362 16T301 -15T250 -22Q224 -22 198 -16T137 16T82 83Q39 165 39 320Q39 494 96 585ZM321 597Q291 629 250 629Q208 629 178 597Q153 571 145 525T137 333Q137 175 145 125T181 46Q209 16 250 16Q290 16 318 46Q347 76 354 130T362 333Q362 478 354 524T321 597Z" transform="translate(1000,0)" style="stroke-width:3;"></path></g><g data-mml-node="mo" transform="translate(1500,0)"><path data-c="2C" d="M78 35T78 60T94 103T137 121Q165 121 187 96T210 8Q210 -27 201 -60T180 -117T154 -158T130 -185T117 -194Q113 -194 104 -185T95 -172Q95 -168 106 -156T131 -126T157 -76T173 -3V9L172 8Q170 7 167 6T161 3T152 1T140 0Q113 0 96 17Z" style="stroke-width:3;"></path></g><g data-mml-node="msup" transform="translate(1944.7,0)"><g data-mml-node="mn"><path data-c="30" d="M96 585Q152 666 249 666Q297 666 345 640T423 548Q460 465 460 320Q460 165 417 83Q397 41 362 16T301 -15T250 -22Q224 -22 198 -16T137 16T82 83Q39 165 39 320Q39 494 96 585ZM321 597Q291 629 250 629Q208 629 178 597Q153 571 145 525T137 333Q137 175 145 125T181 46Q209 16 250 16Q290 16 318 46Q347 76 354 130T362 333Q362 478 354 524T321 597Z" style="stroke-width:3;"></path><path data-c="30" d="M96 585Q152 666 249 666Q297 666 345 640T423 548Q460 465 460 320Q460 165 417 83Q397 41 362 16T301 -15T250 -22Q224 -22 198 -16T137 16T82 83Q39 165 39 320Q39 494 96 585ZM321 597Q291 629 250 629Q208 629 178 597Q153 571 145 525T137 333Q137 175 145 125T181 46Q209 16 250 16Q290 16 318 46Q347 76 354 130T362 333Q362 478 354 524T321 597Z" transform="translate(500,0)" style="stroke-width:3;"></path><path data-c="30" d="M96 585Q152 666 249 666Q297 666 345 640T423 548Q460 465 460 320Q460 165 417 83Q397 41 362 16T301 -15T250 -22Q224 -22 198 -16T137 16T82 83Q39 165 39 320Q39 494 96 585ZM321 597Q291 629 250 629Q208 629 178 597Q153 571 145 525T137 333Q137 175 145 125T181 46Q209 16 250 16Q290 16 318 46Q347 76 354 130T362 333Q362 478 354 524T321 597Z" transform="translate(1000,0)" style="stroke-width:3;"></path></g><g data-mml-node="TeXAtom" transform="translate(1533,393.1) scale(0.707)" data-mjx-texclass="ORD"><g data-mml-node="mn"><path data-c="31" d="M213 578L200 573Q186 568 160 563T102 556H83V602H102Q149 604 189 617T245 641T273 663Q275 666 285 666Q294 666 302 660V361L303 61Q310 54 315 52T339 48T401 46H427V0H416Q395 3 257 3Q121 3 100 0H88V46H114Q136 46 152 46T177 47T193 50T201 52T207 57T213 61V578Z" style="stroke-width:3;"></path><path data-c="30" d="M96 585Q152 666 249 666Q297 666 345 640T423 548Q460 465 460 320Q460 165 417 83Q397 41 362 16T301 -15T250 -22Q224 -22 198 -16T137 16T82 83Q39 165 39 320Q39 494 96 585ZM321 597Q291 629 250 629Q208 629 178 597Q153 571 145 525T137 333Q137 175 145 125T181 46Q209 16 250 16Q290 16 318 46Q347 76 354 130T362 333Q362 478 354 524T321 597Z" transform="translate(500,0)" style="stroke-width:3;"></path></g></g></g></g></g>',1)]))),t[1]||(t[1]=e("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[e("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[e("mn",null,"100"),e("mo",null,","),e("msup",null,[e("mn",null,"000"),e("mrow",{"data-mjx-texclass":"ORD"},[e("mn",null,"10")])])])],-1))]),t[4]||(t[4]=o("。这个数字比宇宙中的原子数量还要多。"))]),t[6]||(t[6]=e("li",null,[e("strong",null,"后果"),o("：AI 永远无法看完所有可能的句子。如果有一句话 AI 没见过（哪怕只改了一个逗号），它就无法对应到任何数字，彻底“宕机”。")],-1))]),t[8]||(t[8]=a('<p><strong>Token 的逻辑是</strong>：我只需要记住几万块“积木”（Token），就可以通过不同的组合，拼出无限种句子。<strong>这叫“生成能力”，而不是“查表能力”。</strong></p><hr><h5 id="_2-泛化能力-ai-必须能-举一反三" tabindex="-1">2. 泛化能力（AI 必须能“举一反三”） <a class="header-anchor" href="#_2-泛化能力-ai-必须能-举一反三" aria-label="Permalink to &quot;2. 泛化能力（AI 必须能“举一反三”）&quot;">​</a></h5><p>如果 AI 把一整句话看作一个孤立的数字，它就失去了理解<strong>内部结构</strong>的能力。</p><ul><li><strong>句子 A</strong>：“猫在写代码。”（数字 ID：1001）</li><li><strong>句子 B</strong>：“狗在写代码。”（数字 ID：9999）</li><li>如果它们是两个独立的数字，AI 无法从数学上发现这两句话其实只有一个词的区别。</li><li><strong>Token 的逻辑是</strong>：AI 看到 <code>猫</code> + <code>在</code> + <code>写代码</code>。当它下次看到 <code>狗</code> 时，它能利用之前学习到的 <code>在写代码</code> 的规律，立刻理解“狗在写代码”是什么意思。</li></ul><h5 id="_3-预测下一个字-的任务本质" tabindex="-1">3. “预测下一个字”的任务本质 <a class="header-anchor" href="#_3-预测下一个字-的任务本质" aria-label="Permalink to &quot;3. “预测下一个字”的任务本质&quot;">​</a></h5><p>目前主流的大模型（Transformer 架构）本质上都是<strong>概率预测引擎</strong>。</p><p>AI 的工作流程是：</p><ol><li>输入一串数字（Token 序列）。</li><li>计算：根据前面的数字，下一个数字最可能是谁？</li><li>输出：预测出的那个数字。</li></ol><p><strong>如果一整句话就是一个数字，那么 AI 就无法在句子内部进行推理。</strong> 它只能预测“下一句话”，这会导致生成的颗粒度太粗，根本无法进行细腻的对话或严谨的代码编写。</p>',10))])}const k=s(r,[["render",i]]);export{u as __pageData,k as default};
